import type { ReactNode } from "react";
import { ActivityFeed } from "@/shared/ui/data/ActivityFeed";
import { Donut, Legend, LineArea, Spark, StatCard, type DonutSlice, type LineSeries } from "@/shared/ui/charts";
import { PageHeader } from "@/shared/ui/pages/PageHeader";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Grid } from "@/shared/ui/layout/Grid";
import { Box } from "@/shared/ui/layout/Box";
import { Card } from "@/shared/ui/data/Card";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import type { ActivityItem } from "@/shared/ui/data/ActivityFeed";

export type StatTone = "fg" | "accent" | "info" | "success" | "danger";
export interface DashboardStat {
  k: string;
  v: ReactNode;
  sub?: ReactNode;
  tone?: StatTone;
  trend?: number[];
  trendColor?: string;
}
export interface DashboardTrend {
  title: string;
  hint?: string;
  labels: string[];
  series: LineSeries[];
}
export interface DashboardBreakdown {
  title: string;
  hint?: string;
  slices: DonutSlice[];
}
export interface DashboardActivity {
  hint: string;
  items: ActivityItem[];
  tone: Record<string, string>;
}
export interface DashboardPageProps {
  title?: ReactNode;
  hint?: ReactNode;
  toolbar?: ReactNode;
  stats?: DashboardStat[];
  trend?: DashboardTrend;
  breakdown?: DashboardBreakdown;
  activity?: DashboardActivity;
  className?: string;
  loading?: boolean;
}
const DEMO_STATS: DashboardStat[] = [
  { k: "landed", v: 12, tone: "success", trend: [3, 5, 4, 8, 12] },
  { k: "blocked", v: 1, tone: "danger", sub: "1 waiting" },
];
const DEMO_TREND: DashboardTrend = {
  title: "Throughput", hint: "7d", labels: ["m", "t", "w", "th", "f"],
  series: [{ name: "landed", color: "var(--success)", data: [3, 5, 4, 8, 12] }],
};
const DEMO_BREAKDOWN: DashboardBreakdown = {
  title: "By state",
  slices: [{ name: "landed", value: 12, color: "var(--success)" }, { name: "open", value: 4, color: "var(--accent)" }],
};
const DEMO_ACTIVITY: DashboardActivity = {
  hint: "across all repos",
  items: [{ login: "octocat", action: "merged", target: "#412 live fleet roster", repo: "acme/api", createdAt: new Date(Date.now() - 3600000).toISOString() }],
  tone: { merged: "var(--success)" },
};
export function DashboardPage({
  title = "Dashboard", hint, toolbar,
  stats = DEMO_STATS, trend = DEMO_TREND, breakdown = DEMO_BREAKDOWN, activity = DEMO_ACTIVITY, className, loading = false,
}: DashboardPageProps) {
  const charts = loading ? (
    <Stack gap={16} style={{ minWidth: 0 }}>
      <Card><Skeleton h={150} radius={8} /></Card>
    </Stack>
  ) : (
    <Stack gap={16} style={{ minWidth: 0 }}>
      {trend && (
        <Card title={trend.title} hint={trend.hint}>
          <LineArea series={trend.series} labels={trend.labels} height={150} />
        </Card>
      )}
      {breakdown && (
        <Card title={breakdown.title} hint={breakdown.hint}>
          <Row gap={20} align="center" wrap>
            <Donut slices={breakdown.slices} />
            <Legend items={breakdown.slices.map((s) => ({ color: s.color, label: s.name, value: s.value }))} />
          </Row>
        </Card>
      )}
    </Stack>
  );

  return (
    <Stack gap={0} className={className} style={{ flex: 1, minHeight: 0, overflow: "hidden" }}>
      <PageHeader title={title} hint={hint} toolbar={toolbar} />
      <Box pad={16} style={{ flex: 1, minHeight: 0, overflowY: "auto" }}>
        <Stack gap={16}>
          {stats.length > 0 && (
            <Grid cols="repeat(auto-fit, minmax(150px, 1fr))" gap={12}>
              {stats.map((s) => (
                <StatCard key={s.k} k={s.k} v={s.v} tone={s.tone} loading={loading}
                  sub={
                    s.trend && s.trend.length >= 2
                      ? <Row gap={8} align="center" inline>{s.sub}<Spark data={s.trend} color={s.trendColor ?? "var(--accent)"} /></Row>
                      : s.sub
                  } />
              ))}
            </Grid>
          )}
          {(trend || breakdown || activity || loading) && (
            activity || loading ? (
              <Grid cols="minmax(0, 2fr) minmax(0, 1fr)" gap={16} align="start">
                {charts}
                {loading ? <Card><Skeleton h={200} radius={8} /></Card> : <ActivityFeed items={activity!.items} hint={activity!.hint} tone={activity!.tone} />}
              </Grid>
            ) : charts
          )}
        </Stack>
      </Box>
    </Stack>
  );
}

